/bin/bash -lc "cat > /tmp/cdp_actions.py <<'PY'
import socket, base64, os, json, struct, sys, urllib.request, time
urllib.request.install_opener(urllib.request.build_opener(urllib.request.ProxyHandler({})))
pages=json.load(urllib.request.urlopen('http://127.0.0.1:1337/json/list'))
page=next(p for p in pages if p.get('type')=='page')
ws=page['webSocketDebuggerUrl']
hostport,path=ws[5:].split('/',1); path='/'+path
host,port=hostport.split(':'); port=int(port)
s=socket.create_connection((host,port))
key=base64.b64encode(os.urandom(16)).decode()
s.sendall((f\"GET {path} HTTP/1.1\\r\\nHost: {hostport}\\r\\nUpgrade: websocket\\r\\nConnection: Upgrade\\r\\nSec-WebSocket-Key: {key}\\r\\nSec-WebSocket-Version: 13\\r\\n\\r\\n\").encode())
resp=s.recv(4096)
if b'101' not in resp.split(b'\\r\\n',1)[0]: print(resp); sys.exit(1)
mid=0

def send(obj):
 data=json.dumps(obj).encode(); h=bytearray([0x81]); n=len(data)
 if n<126: h.append(0x80|n)
 elif n<65536: h += bytes([0x80|126])+struct.pack('"'!H'"',n)
 else: h += bytes([0x80|127])+struct.pack('"'!Q'"',n)
 mask=os.urandom(4); h+=mask
 s.sendall(h+bytes(b"'^mask[i%4] for i,b in enumerate(data)))

def recv():
 h=s.recv(2); b1,b2=h; n=b2&0x7f
 if n==126: n=struct.unpack('"'"'!H'"',s.recv(2))[0]
 elif n==127: n=struct.unpack('"'!Q'"',s.recv(8))[0]
 mask=s.recv(4) if b2&0x80 else None
 data=b''
 while len(data)<n: data += s.recv(n-len(data))
 if mask: data=bytes(b"'^mask[i%4] for i,b in enumerate(data))
 if (b1&0xf)==8: raise EOFError
 return json.loads(data.decode()) if data else None

def cmd(method, params=None, timeout=10):
 global mid; mid += 1; ident=mid
 send({'"'id':ident,'method':method,'params':params or {}})
 end=time.time()+timeout
 while time.time()<end:
  m=recv()
  if m and m.get('id')==ident: return m
 raise TimeoutError(method)

def click(x,y):
 cmd('Input.dispatchMouseEvent', {'type':'mouseMoved','x':x,'y':y})
 cmd('Input.dispatchMouseEvent', {'type':'mousePressed','x':x,'y':y,'button':'left','clickCount':1})
 cmd('Input.dispatchMouseEvent', {'type':'mouseReleased','x':x,'y':y,'button':'left','clickCount':1})

def key(key, text=None, code=None):
 p={'type':'keyDown','key':key,'windowsVirtualKeyCode':ord(key.upper()) if len(key)==1 else 0}
 if code: p['code']=code
 if text: p['text']=text
 cmd('Input.dispatchKeyEvent', p)
 p['type']='keyUp'; p.pop('text',None); cmd('Input.dispatchKeyEvent', p)

def type_text(t):
 cmd('Input.insertText', {'text':t})

for line in sys.stdin:
 parts=line.strip().split(' ',2)
 if not parts or not parts[0] or parts[0].startswith('#'): continue
 if parts[0]=='click': click(float(parts[1]), float(parts[2]))
 elif parts[0]=='type': type_text(parts[1] if len(parts)==2 else parts[2])
 elif parts[0]=='sleep': time.sleep(float(parts[1]))
 elif parts[0]=='key': key(parts[1])
 elif parts[0]=='eval': print(cmd('Runtime.evaluate', {'expression':parts[1] if len(parts)==2 else parts[2], 'returnByValue':True}))
print('done')
PY"

